import axios from 'axios';
import { API_BASE_URL } from './constants';

const api = axios.create({
  baseURL: API_BASE_URL,
  timeout: 15_000,
});

// ── Risk ────────────────────────────────────────────────────────────────────
export const getRiskScore = (payload) => api.post('/risk/score', payload);

// ── Journey ─────────────────────────────────────────────────────────────────
export const startJourney = (payload) => api.post('/journey/start', payload);
export const pingJourney  = (payload) => api.post('/journey/ping', payload);
export const endJourney   = (journey_id) => api.post('/journey/end', { journey_id });

// ── Alerts ───────────────────────────────────────────────────────────────────
export const triggerAlert = (payload) => api.post('/alerts/trigger', payload);

// ── Hotspots ─────────────────────────────────────────────────────────────────
export const getNearbyHotspots = (lat, lng) =>
  api.get('/hotspot/nearby', { params: { lat, lng } });

// ── Signals ──────────────────────────────────────────────────────────────────
export const getNearbySignals  = (lat, lng) =>
  api.get('/signals/nearby', { params: { lat, lng } });
export const getAllSignals      = ()         => api.get('/signals/map');

// ── Incidents ────────────────────────────────────────────────────────────────
export const reportIncident = (payload) => api.post('/incident/report', payload);

export default api;

