  View, Text, TextInput, TouchableOpacity,
  StyleSheet, ScrollView, Alert,
} from 'react-native';
import { getAuth, signInWithPhoneNumber, PhoneAuthProvider, signInWithCredential } from 'firebase/auth';
import { doc, setDoc } from 'firebase/firestore';
import { db, auth } from '../utils/firebase';
import { TRAVEL_MODES } from '../utils/constants';

const STEPS = { PHONE: 0, OTP: 1, NAME: 2, MODE: 3, CONTACTS: 4, PERMISSIONS: 5 };

export default function Onboarding({ navigation }) {
  const [step, setStep] = useState(STEPS.PHONE);
  const [phone, setPhone] = useState('');
  const [otp, setOtp] = useState('');
  const [name, setName] = useState('');
  const [travelMode, setTravelMode] = useState('solo');
  const [contacts, setContacts] = useState([{ name: '', phone: '', relation: '' }]);
  const [verificationId, setVerificationId] = useState(null);

  const sendOTP = async () => {
    try {
      const confirmation = await signInWithPhoneNumber(auth, `+92${phone}`);
      setVerificationId(confirmation.verificationId);
      setStep(STEPS.OTP);
    } catch (e) {
      Alert.alert('Error', e.message);
    }
  };

  const verifyOTP = async () => {
    try {
      const credential = PhoneAuthProvider.credential(verificationId, otp);
      await signInWithCredential(auth, credential);
      setStep(STEPS.NAME);
    } catch (e) {
      Alert.alert('Invalid OTP', 'Please try again.');
    }
  };

  const saveProfile = async () => {
    const user = auth.currentUser;
    await setDoc(doc(db, 'users', user.uid), {
      name,
      phone: `+92${phone}`,
      travel_mode: travelMode,
      contacts: contacts.filter(c => c.name && c.phone),
      createdAt: new Date().toISOString(),
    });
    navigation.replace('Home');
  };

  const updateContact = (index, field, value) => {
    const updated = [...contacts];
    updated[index][field] = value;
    setContacts(updated);
  };

  return (
    <ScrollView contentContainerStyle={s.container}>
      {step === STEPS.PHONE && (
        <View style={s.card}>
          <Text style={s.title}>🛡️ Bachao Pakistan</Text>
          <Text style={s.subtitle}>Predicting Danger Before It Finds You</Text>
          <Text style={s.label}>Enter your phone number</Text>
          <View style={s.phoneRow}>
            <Text style={s.countryCode}>+92</Text>
            <TextInput style={s.input} keyboardType="phone-pad" value={phone}
              onChangeText={setPhone} placeholder="3001234567" placeholderTextColor="#64748b" />
          </View>
          <TouchableOpacity style={s.btn} onPress={sendOTP}>
            <Text style={s.btnText}>Send OTP</Text>
          </TouchableOpacity>
        </View>
      )}

      {step === STEPS.OTP && (
        <View style={s.card}>
          <Text style={s.title}>Enter OTP</Text>
          <Text style={s.subtitle}>Sent to +92{phone}</Text>
          <TextInput style={s.input} keyboardType="number-pad" value={otp}
            onChangeText={setOtp} placeholder="000000" placeholderTextColor="#64748b" maxLength={6} />
          <TouchableOpacity style={s.btn} onPress={verifyOTP}>
            <Text style={s.btnText}>Verify</Text>
          </TouchableOpacity>
        </View>
      )}

      {step === STEPS.NAME && (
        <View style={s.card}>
          <Text style={s.title}>Your Name</Text>
          <TextInput style={s.input} value={name} onChangeText={setName}
            placeholder="Full name" placeholderTextColor="#64748b" />
          <TouchableOpacity style={s.btn} onPress={() => name && setStep(STEPS.MODE)}>
            <Text style={s.btnText}>Continue</Text>
          </TouchableOpacity>
        </View>
      )}

      {step === STEPS.MODE && (
        <View style={s.card}>
          <Text style={s.title}>How do you usually travel?</Text>
          {TRAVEL_MODES.map(m => (
            <TouchableOpacity key={m.id} style={[s.modeBtn, travelMode === m.id && s.modeBtnActive]}
              onPress={() => setTravelMode(m.id)}>
              <Text style={s.modeBtnText}>{m.icon} {m.label}</Text>
            </TouchableOpacity>
          ))}
          <TouchableOpacity style={[s.btn, { marginTop: 20 }]} onPress={() => setStep(STEPS.CONTACTS)}>
            <Text style={s.btnText}>Continue</Text>
          </TouchableOpacity>
        </View>
      )}

      {step === STEPS.CONTACTS && (
        <View style={s.card}>
          <Text style={s.title}>Trusted Contacts</Text>
          <Text style={s.subtitle}>Up to 3 people we'll call if you don't arrive</Text>
          {contacts.map((c, i) => (
            <View key={i} style={s.contactBlock}>
              <Text style={s.label}>Contact {i + 1}</Text>
              <TextInput style={s.input} placeholder="Name" value={c.name}
                onChangeText={v => updateContact(i, 'name', v)} placeholderTextColor="#64748b" />
              <TextInput style={s.input} placeholder="Phone (03xxxxxxxxx)" value={c.phone}
                keyboardType="phone-pad" onChangeText={v => updateContact(i, 'phone', v)} placeholderTextColor="#64748b" />
              <TextInput style={s.input} placeholder="Relationship (e.g. Father)" value={c.relation}
                onChangeText={v => updateContact(i, 'relation', v)} placeholderTextColor="#64748b" />
            </View>
          ))}
          {contacts.length < 3 && (
            <TouchableOpacity onPress={() => setContacts([...contacts, { name: '', phone: '', relation: '' }])}>
              <Text style={s.addContact}>+ Add another contact</Text>
            </TouchableOpacity>
          )}
          <TouchableOpacity style={[s.btn, { marginTop: 20 }]} onPress={saveProfile}>
            <Text style={s.btnText}>Finish Setup</Text>
          </TouchableOpacity>
        </View>
      )}
    </ScrollView>
  );
}

const s = StyleSheet.create({
  container:    { flexGrow: 1, backgroundColor: '#0f172a', padding: 24, justifyContent: 'center' },
  card:         { backgroundColor: '#1e293b', borderRadius: 16, padding: 24 },
  title:        { color: '#f8fafc', fontSize: 24, fontWeight: 'bold', marginBottom: 8 },
  subtitle:     { color: '#94a3b8', fontSize: 14, marginBottom: 24 },
  label:        { color: '#94a3b8', fontSize: 12, marginBottom: 6, marginTop: 12 },
  phoneRow:     { flexDirection: 'row', alignItems: 'center', gap: 8 },
  countryCode:  { color: '#f8fafc', fontSize: 16, backgroundColor: '#334155', padding: 14, borderRadius: 10 },
  input:        { backgroundColor: '#334155', color: '#f8fafc', borderRadius: 10, padding: 14, fontSize: 16, marginBottom: 12 },
  btn:          { backgroundColor: '#ef4444', borderRadius: 12, padding: 16, alignItems: 'center' },
  btnText:      { color: '#fff', fontSize: 16, fontWeight: 'bold' },
  modeBtn:      { backgroundColor: '#334155', borderRadius: 10, padding: 16, marginBottom: 10 },
  modeBtnActive:{ backgroundColor: '#ef4444' },
  modeBtnText:  { color: '#f8fafc', fontSize: 16 },
  contactBlock: { borderTopWidth: 1, borderTopColor: '#334155', paddingTop: 12, marginTop: 12 },
  addContact:   { color: '#ef4444', textAlign: 'center', marginTop: 8 },
});

