import { useEffect, useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, ScrollView, Alert } from 'react-native';
import * as Location from 'expo-location';
import { getAuth } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../utils/firebase';
import { getNearbyHotspots, getNearbySignals } from '../utils/api';
import { TRAVEL_MODES, RISK_COLORS } from '../utils/constants';
import RiskBadge from '../components/RiskBadge';

export default function Home({ navigation }) {
  const [user, setUser]             = useState(null);
  const [location, setLocation]     = useState(null);
  const [hotspots, setHotspots]     = useState([]);
  const [signals, setSignals]       = useState([]);
  const [travelMode, setTravelMode] = useState('solo');

  useEffect(() => {
    loadUser();
    requestLocation();
  }, []);

  const loadUser = async () => {
    const u = getAuth().currentUser;
    if (u) {
      const snap = await getDoc(doc(db, 'users', u.uid));
      if (snap.exists()) {
        const data = snap.data();
        setUser(data);
        setTravelMode(data.travel_mode || 'solo');
      }
    }
  };

  const requestLocation = async () => {
    const { status } = await Location.requestForegroundPermissionsAsync();
    if (status !== 'granted') {
      Alert.alert('Location Required', 'Bachao Pakistan needs location to protect you.');
      return;
    }
    const loc = await Location.getCurrentPositionAsync({});
    setLocation(loc.coords);
    fetchNearby(loc.coords.latitude, loc.coords.longitude);
  };

  const fetchNearby = async (lat, lng) => {
    try {
      const [hs, sigs] = await Promise.all([
        getNearbyHotspots(lat, lng),
        getNearbySignals(lat, lng),
      ]);
      setHotspots(hs.data);
      setSignals(sigs.data);
    } catch (e) {
      console.warn('Failed to load nearby data', e.message);
    }
  };

  const highRiskSignals = signals.filter(s => s.current_risk_level === 'HIGH');

  return (
    <ScrollView style={s.container}>
      <View style={s.header}>
        <Text style={s.greeting}>Hello, {user?.name?.split(' ')[0] || 'there'} 👋</Text>
        <Text style={s.sub}>Stay safe tonight.</Text>
      </View>

      {/* Mode Toggle */}
      <View style={s.modeRow}>
        {TRAVEL_MODES.map(m => (
          <TouchableOpacity key={m.id} style={[s.modeChip, travelMode === m.id && s.modeChipActive]}
            onPress={() => setTravelMode(m.id)}>
            <Text style={s.modeChipText}>{m.icon}</Text>
          </TouchableOpacity>
        ))}
      </View>

      {/* Biker signal warning */}
      {travelMode === 'biker' && highRiskSignals.length > 0 && (
        <View style={s.bikerAlert}>
          <Text style={s.bikerAlertText}>
            ⚠️ {highRiskSignals.length} high-risk signal{highRiskSignals.length > 1 ? 's' : ''} on common routes near you tonight
          </Text>
        </View>
      )}

      {/* Nearby hotspots summary */}
      <View style={s.section}>
        <Text style={s.sectionTitle}>Nearby Activity</Text>
        <Text style={s.sectionSub}>{hotspots.length} crime zones within 5km</Text>
      </View>

      {/* CTA Buttons */}
      <TouchableOpacity style={s.startBtn}
        onPress={() => navigation.navigate('JourneySetup', { travelMode })}>
        <Text style={s.startBtnText}>Start Journey</Text>
      </TouchableOpacity>

      {travelMode === 'biker' && (
        <TouchableOpacity style={s.signalBtn}
          onPress={() => navigation.navigate('SafeSignals')}>
          <Text style={s.signalBtnText}>🚦 Safe Signals Map</Text>
        </TouchableOpacity>
      )}

      <TouchableOpacity style={s.reportBtn}
        onPress={() => navigation.navigate('IncidentReport')}>
        <Text style={s.reportBtnText}>+ Report Incident</Text>
      </TouchableOpacity>

      {/* Recent high-risk signals */}
      {signals.slice(0, 3).map((sig, i) => (
        <View key={i} style={[s.signalCard, { borderLeftColor: RISK_COLORS[sig.current_risk_level] }]}>
          <Text style={s.signalName}>{sig.name}</Text>
          <Text style={s.signalMeta}>{sig.incident_count_week} incidents this week · {sig.distance_km}km away</Text>
          <RiskBadge level={sig.current_risk_level} />
        </View>
      ))}
    </ScrollView>
  );
}

const s = StyleSheet.create({
  container:       { flex: 1, backgroundColor: '#0f172a' },
  header:          { padding: 24, paddingTop: 60 },
  greeting:        { color: '#f8fafc', fontSize: 26, fontWeight: 'bold' },
  sub:             { color: '#94a3b8', fontSize: 14, marginTop: 4 },
  modeRow:         { flexDirection: 'row', paddingHorizontal: 24, gap: 10, marginBottom: 16 },
  modeChip:        { flex: 1, backgroundColor: '#1e293b', borderRadius: 12, padding: 14, alignItems: 'center' },
  modeChipActive:  { backgroundColor: '#ef4444' },
  modeChipText:    { fontSize: 22 },
  bikerAlert:      { marginHorizontal: 24, backgroundColor: '#431407', borderRadius: 12, padding: 14, marginBottom: 16 },
  bikerAlertText:  { color: '#fca5a5', fontSize: 14 },
  section:         { paddingHorizontal: 24, marginBottom: 16 },
  sectionTitle:    { color: '#f8fafc', fontSize: 18, fontWeight: '600' },
  sectionSub:      { color: '#64748b', fontSize: 13 },
  startBtn:        { marginHorizontal: 24, backgroundColor: '#ef4444', borderRadius: 16, padding: 18, alignItems: 'center', marginBottom: 12 },
  startBtnText:    { color: '#fff', fontSize: 18, fontWeight: 'bold' },
  signalBtn:       { marginHorizontal: 24, backgroundColor: '#1e293b', borderRadius: 16, padding: 16, alignItems: 'center', marginBottom: 12, borderWidth: 1, borderColor: '#f59e0b' },
  signalBtnText:   { color: '#f59e0b', fontSize: 16, fontWeight: '600' },
  reportBtn:       { marginHorizontal: 24, backgroundColor: '#1e293b', borderRadius: 16, padding: 14, alignItems: 'center', marginBottom: 24 },
  reportBtnText:   { color: '#94a3b8', fontSize: 15 },
  signalCard:      { marginHorizontal: 24, marginBottom: 10, backgroundColor: '#1e293b', borderRadius: 12, padding: 14, borderLeftWidth: 4 },
  signalName:      { color: '#f8fafc', fontSize: 15, fontWeight: '600' },
  signalMeta:      { color: '#64748b', fontSize: 12, marginTop: 2 },
});

