import { useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, StyleSheet, ScrollView, ActivityIndicator } from 'react-native';
import * as Location from 'expo-location';
import { getAuth } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '../utils/firebase';
import { getRiskScore, startJourney } from '../utils/api';
import { TRAVEL_MODES, RISK_COLORS } from '../utils/constants';
import RiskBadge from '../components/RiskBadge';

export default function JourneySetup({ route, navigation }) {
  const initialMode = route.params?.travelMode || 'solo';
  const [travelMode, setTravelMode]   = useState(initialMode);
  const [destination, setDestination] = useState('');
  const [destCoords, setDestCoords]   = useState(null);
  const [plate, setPlate]             = useState('');
  const [loading, setLoading]         = useState(false);
  const [riskResult, setRiskResult]   = useState(null);
  const [journeyData, setJourneyData] = useState(null);

  const handleConfirm = async () => {
    setLoading(true);
    try {
      const loc = await Location.getCurrentPositionAsync({});
      const { latitude: oLat, longitude: oLng } = loc.coords;

      // TODO: Use Google Places API to resolve destination to coords
      // For now using a mock destination — replace with real geocoding
      const dLat = destCoords?.lat || 24.8607;
      const dLng = destCoords?.lng || 67.0104;

      const now = new Date();
      const timeStr = `${now.getHours().toString().padStart(2,'0')}:${now.getMinutes().toString().padStart(2,'0')}`;
      const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];

      const riskResp = await getRiskScore({
        origin_lat: oLat, origin_lng: oLng,
        destination_lat: dLat, destination_lng: dLng,
        time_of_day: timeStr,
        day_of_week: days[now.getDay()],
        journey_type: travelMode,
      });
      setRiskResult(riskResp.data);

      const userSnap = await getDoc(doc(db, 'users', getAuth().currentUser.uid));
      const userData = userSnap.data();
      const contact = userData.contacts?.[0] || {};

      const journeyResp = await startJourney({
        user_id: getAuth().currentUser.uid,
        origin_lat: oLat, origin_lng: oLng,
        destination_lat: dLat, destination_lng: dLng,
        contact_phone: contact.phone || '',
        contact_name: contact.name || '',
        risk_level: riskResp.data.risk_level,
        journey_type: travelMode,
        plate_number: plate || null,
      });
      setJourneyData(journeyResp.data);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleStart = () => {
    navigation.replace('JourneyActive', {
      journeyId: journeyData.journey_id,
      riskLevel: riskResult.risk_level,
      timerSeconds: journeyData.timer_duration_seconds,
      signalsOnRoute: journeyData.signals_on_route,
      travelMode,
    });
  };

  return (
    <ScrollView style={s.container}>
      <View style={s.header}>
        <Text style={s.title}>Plan Your Journey</Text>
      </View>

      {/* Mode selector */}
      <View style={s.section}>
        <Text style={s.label}>Travel Mode</Text>
        <View style={s.modeRow}>
          {TRAVEL_MODES.map(m => (
            <TouchableOpacity key={m.id} style={[s.modeChip, travelMode === m.id && s.modeChipActive]}
              onPress={() => setTravelMode(m.id)}>
              <Text style={s.modeIcon}>{m.icon}</Text>
              <Text style={s.modeLabel}>{m.label}</Text>
            </TouchableOpacity>
          ))}
        </View>
      </View>

      <View style={s.section}>
        <Text style={s.label}>Destination</Text>
        <TextInput style={s.input} value={destination} onChangeText={setDestination}
          placeholder="Search destination..." placeholderTextColor="#64748b" />
        {/* TODO: Wire up Google Places Autocomplete here */}
      </View>

      {travelMode === 'ride_hailing' && (
        <View style={s.section}>
          <Text style={s.label}>Vehicle Plate Number</Text>
          <TextInput style={s.input} value={plate} onChangeText={setPlate}
            placeholder="e.g. ABC-123" placeholderTextColor="#64748b" />
        </View>
      )}

      {!riskResult && (
        <TouchableOpacity style={s.btn} onPress={handleConfirm} disabled={loading}>
          {loading ? <ActivityIndicator color="#fff" /> : <Text style={s.btnText}>Check Risk & Continue</Text>}
        </TouchableOpacity>
      )}

      {riskResult && (
        <View style={s.riskCard}>
          <RiskBadge level={riskResult.risk_level} large />
          <Text style={s.riskScore}>Score: {(riskResult.risk_score * 100).toFixed(0)}%</Text>

          {riskResult.risk_factors.map((f, i) => (
