import { useEffect, useRef, useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, Vibration, Alert } from 'react-native';
import * as Location from 'expo-location';
import { pingJourney, endJourney, triggerAlert } from '../utils/api';
import { GPS_POLL_INTERVAL_MS } from '../utils/constants';
import TimerRing from '../components/TimerRing';
import RiskBadge from '../components/RiskBadge';
import SignalWarning from '../components/SignalWarning';
import ShakeDetector from '../components/ShakeDetector';
import LocationPoller from '../components/LocationPoller';

export default function JourneyActive({ route, navigation }) {
  const { journeyId, riskLevel, timerSeconds, signalsOnRoute, travelMode } = route.params;

  const [timeLeft, setTimeLeft]               = useState(timerSeconds);
  const [signalWarning, setSignalWarning]     = useState(null);
  const [statusBanner, setStatusBanner]       = useState(null);
  const currentLocation                        = useRef(null);
  const timerRef                               = useRef(null);
  const pollerRef                              = useRef(null);

  useEffect(() => {
    // Countdown timer
    timerRef.current = setInterval(() => {
      setTimeLeft(t => {
        if (t <= 1) {
          clearInterval(timerRef.current);
          handleAlert('timer_expired');
          return 0;
        }
        return t - 1;
      });
    }, 1000);

    return () => {
      clearInterval(timerRef.current);
    };
  }, []);

  const handlePingResponse = async (pingResp) => {
    const { status, message, signal_data } = pingResp;

    if (status === 'alert') {
      handleAlert('route_deviation');
    } else if (status === 'deviation') {
      setStatusBanner({ type: 'warning', text: message });
      setTimeout(() => setStatusBanner(null), 5000);
    } else if (status === 'stop') {
      Alert.alert('Are you okay?', message, [
        { text: "I'm Safe", style: 'default' },
        { text: 'Send SOS', onPress: () => handleAlert('unusual_stop'), style: 'destructive' },
      ]);
    } else if (status === 'signal_warning') {
      Vibration.vibrate([0, 400, 200, 400, 200, 400]);
      setSignalWarning(signal_data);
    }
  };

  const handleAlert = async (triggerType) => {
    const loc = currentLocation.current;
    if (!loc) return;
    try {
      await triggerAlert({
        journey_id: journeyId,
        trigger_type: triggerType,
        current_lat: loc.latitude,
        current_lng: loc.longitude,
      });
    } catch (e) {
      console.error('Alert trigger failed', e);
    }
  };

  const handleSafe = async () => {
    clearInterval(timerRef.current);
    await endJourney(journeyId);
    navigation.replace('SafeArrival');
  };

  return (
    <View style={s.container}>
      <RiskBadge level={riskLevel} large style={{ alignSelf: 'center', marginTop: 60 }} />

      <TimerRing secondsLeft={timeLeft} totalSeconds={timerSeconds} />

      <Text style={s.status}>Running silently in background</Text>

      {statusBanner && (
        <View style={[s.banner, statusBanner.type === 'warning' ? s.bannerWarn : s.bannerOk]}>
          <Text style={s.bannerText}>{statusBanner.text}</Text>
        </View>
      )}

      {/* Background processes */}
      <ShakeDetector onShake={() => handleAlert('manual_sos')} />
      <LocationPoller
        journeyId={journeyId}
        onLocation={coords => { currentLocation.current = coords; }}
        onPingResponse={handlePingResponse}
      />

      {/* Signal warning overlay */}
      {signalWarning && (
        <SignalWarning
          signal={signalWarning}
          onDismiss={() => setSignalWarning(null)}
        />
      )}

      <TouchableOpacity style={s.safeBtn} onPress={handleSafe}>
        <Text style={s.safeBtnText}>I'm Safe</Text>
      </TouchableOpacity>
    </View>
  );
}

const s = StyleSheet.create({
  container:  { flex: 1, backgroundColor: '#0f172a', alignItems: 'center' },
  status:     { color: '#64748b', fontSize: 14, marginTop: 16 },
  banner:     { margin: 24, borderRadius: 12, padding: 14, width: '90%' },
  bannerWarn: { backgroundColor: '#431407' },
  bannerOk:   { backgroundColor: '#14532d' },
  bannerText: { color: '#f8fafc', textAlign: 'center' },
  safeBtn:    { position: 'absolute', bottom: 48, backgroundColor: '#22c55e', borderRadius: 50, paddingVertical: 18, paddingHorizontal: 40 },
  safeBtnText:{ color: '#fff', fontSize: 18, fontWeight: 'bold' },
});

