import { useState } from 'react';
import { View, Text, TextInput, TouchableOpacity, StyleSheet, ScrollView, Switch, Alert } from 'react-native';
import * as Location from 'expo-location';
import { reportIncident } from '../utils/api';
import { INCIDENT_TYPES } from '../utils/constants';

const KARACHI_SIGNALS = [
  'Teen Talwar Signal', 'Numaish Signal', 'Hassan Square', 'Baloch Colony Signal',
  'Gulshan Chowrangi', 'Tariq Road Signal', 'Shahra-e-Faisal Signal', 'Other',
];

export default function IncidentReport({ navigation }) {
  const [type, setType]           = useState('');
  const [signalName, setSignalName] = useState('');
  const [description, setDescription] = useState('');
  const [anonymous, setAnonymous] = useState(true);
  const [loading, setLoading]     = useState(false);

  const submit = async () => {
    if (!type) { Alert.alert('Select incident type'); return; }
    setLoading(true);
    try {
      const loc = await Location.getCurrentPositionAsync({});
      await reportIncident({
        type,
        lat: loc.coords.latitude,
        lng: loc.coords.longitude,
        signal_name: signalName || null,
        description,
        anonymous,
      });
      Alert.alert('Reported', 'Thank you. Your report helps protect others.', [
        { text: 'OK', onPress: () => navigation.goBack() },
      ]);
    } catch (e) {
      Alert.alert('Error', 'Could not submit. Try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <ScrollView style={s.container}>
      <View style={s.header}>
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <Text style={s.back}>← Back</Text>
        </TouchableOpacity>
        <Text style={s.title}>Report Incident</Text>
      </View>

      <View style={s.section}>
        <Text style={s.label}>Incident Type</Text>
        {INCIDENT_TYPES.map(t => (
          <TouchableOpacity key={t.id} style={[s.typeBtn, type === t.id && s.typeBtnActive]}
            onPress={() => setType(t.id)}>
            <Text style={s.typeBtnText}>{t.icon} {t.label}</Text>
          </TouchableOpacity>
        ))}
      </View>

      {(type === 'signal_robbery' || type === 'phone_snatching') && (
        <View style={s.section}>
          <Text style={s.label}>Signal Name</Text>
          {KARACHI_SIGNALS.map(sig => (
            <TouchableOpacity key={sig} style={[s.typeBtn, signalName === sig && s.typeBtnActive]}
              onPress={() => setSignalName(sig)}>
              <Text style={s.typeBtnText}>{sig}</Text>
            </TouchableOpacity>
          ))}
        </View>
      )}

      <View style={s.section}>
        <Text style={s.label}>Description (optional)</Text>
        <TextInput style={[s.input, { height: 100, textAlignVertical: 'top' }]}
          value={description} onChangeText={setDescription} multiline
          placeholder="Brief description of what happened..."
          placeholderTextColor="#64748b" />
      </View>

      <View style={s.anonRow}>
        <Text style={s.anonLabel}>Submit anonymously</Text>
        <Switch value={anonymous} onValueChange={setAnonymous} trackColor={{ true: '#ef4444' }} />
      </View>

      <TouchableOpacity style={s.btn} onPress={submit} disabled={loading}>
        <Text style={s.btnText}>{loading ? 'Submitting...' : 'Submit Report'}</Text>
      </TouchableOpacity>
    </ScrollView>
  );
}

const s = StyleSheet.create({
  container:    { flex: 1, backgroundColor: '#0f172a' },
  header:       { padding: 24, paddingTop: 60 },
  back:         { color: '#94a3b8', marginBottom: 12 },
