import { useEffect, useState } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, FlatList, ActivityIndicator } from 'react-native';
import MapView, { Marker, Circle } from 'react-native-maps';
import * as Location from 'expo-location';
import { getAllSignals } from '../utils/api';
import { RISK_COLORS } from '../utils/constants';

const RISK_ICONS = { HIGH: '🔴', MEDIUM: '🟡', LOW: '🟢' };

export default function SafeSignals({ navigation }) {
  const [signals, setSignals]   = useState([]);
  const [selected, setSelected] = useState(null);
  const [filter, setFilter]     = useState('ALL');   // ALL | HIGH | NOW
  const [loading, setLoading]   = useState(true);
  const [region, setRegion]     = useState({
    latitude: 24.8607, longitude: 67.0104,
    latitudeDelta: 0.15, longitudeDelta: 0.15,
  });

  useEffect(() => {
    loadSignals();
    centerOnUser();
  }, []);

  const centerOnUser = async () => {
    const { status } = await Location.requestForegroundPermissionsAsync();
    if (status === 'granted') {
      const loc = await Location.getCurrentPositionAsync({});
      setRegion(r => ({ ...r, latitude: loc.coords.latitude, longitude: loc.coords.longitude }));
    }
  };

  const loadSignals = async () => {
    try {
      const resp = await getAllSignals();
      setSignals(resp.data);
    } catch (e) {
      console.warn(e);
    } finally {
      setLoading(false);
    }
  };

  const filtered = signals.filter(s => {
    if (filter === 'HIGH') return s.current_risk_level === 'HIGH';
    const hour = new Date().getHours();
    if (filter === 'NOW') return s.peak_hours?.includes(hour);
    return true;
  });

  if (loading) return (
    <View style={s.loading}><ActivityIndicator color="#ef4444" size="large" /></View>
  );

  return (
    <View style={s.container}>
      {/* Header */}
      <View style={s.header}>
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <Text style={s.back}>← Back</Text>
        </TouchableOpacity>
        <Text style={s.title}>🚦 Safe Signals Map</Text>
      </View>

      {/* Filter chips */}
      <View style={s.filters}>
        {['ALL','HIGH','NOW'].map(f => (
          <TouchableOpacity key={f} style={[s.chip, filter === f && s.chipActive]}
            onPress={() => setFilter(f)}>
            <Text style={s.chipText}>{f === 'NOW' ? '⚡ Right now' : f}</Text>
          </TouchableOpacity>
        ))}
      </View>

      {/* Map */}
      <MapView style={s.map} region={region} onRegionChangeComplete={setRegion}>
        {filtered.map((sig, i) => (
          <Marker key={i}
            coordinate={{ latitude: sig.lat, longitude: sig.lng }}
            pinColor={RISK_COLORS[sig.current_risk_level]}
            onPress={() => setSelected(sig)}
          />
        ))}
      </MapView>

      {/* Signal detail popup */}
      {selected && (
        <View style={s.popup}>
          <TouchableOpacity style={s.popupClose} onPress={() => setSelected(null)}>
            <Text style={s.popupCloseText}>✕</Text>
          </TouchableOpacity>
          <Text style={s.popupTitle}>{RISK_ICONS[selected.current_risk_level]} {selected.name}</Text>
          <Text style={s.popupMeta}>Risk: {selected.current_risk_level}</Text>
          <Text style={s.popupMeta}>This week: {selected.incident_count_week} incidents</Text>
          <Text style={s.popupMeta}>This month: {selected.incident_count_month} incidents</Text>
          <Text style={s.popupMeta}>Peak hours: {selected.peak_hours?.join('h, ')}h</Text>
          {selected.incident_types?.length > 0 && (
            <Text style={s.popupMeta}>Most common: {selected.incident_types[0]}</Text>
          )}
        </View>
      )}
    </View>
  );
}

const s = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#0f172a' },
  loading:   { flex: 1, justifyContent: 'center', alignItems: 'center', backgroundColor: '#0f172a' },
  header:    { padding: 24, paddingTop: 60 },
  back:      { color: '#94a3b8', marginBottom: 8 },
