  chipActive:{ backgroundColor: '#ef4444' },
  chipText:  { color: '#f8fafc', fontSize: 13 },
  map:       { flex: 1 },
  popup:     { position: 'absolute', bottom: 0, left: 0, right: 0, backgroundColor: '#1e293b', borderTopLeftRadius: 20, borderTopRightRadius: 20, padding: 24, paddingBottom: 40 },
  popupClose:{ position: 'absolute', right: 20, top: 16 },
  popupCloseText: { color: '#64748b', fontSize: 18 },
  popupTitle:{ color: '#f8fafc', fontSize: 18, fontWeight: 'bold', marginBottom: 12 },
  popupMeta: { color: '#94a3b8', fontSize: 14, marginBottom: 4 },
});

