import { View, Text, StyleSheet } from 'react-native';
import Svg, { Circle } from 'react-native-svg';

export default function TimerRing({ secondsLeft, totalSeconds }) {
  const SIZE = 200;
  const STROKE = 12;
  const R = (SIZE - STROKE) / 2;
  const CIRCUMFERENCE = 2 * Math.PI * R;
  const progress = Math.max(secondsLeft / totalSeconds, 0);
  const dashOffset = CIRCUMFERENCE * (1 - progress);

  const minutes = Math.floor(secondsLeft / 60).toString().padStart(2, '0');
  const seconds = (secondsLeft % 60).toString().padStart(2, '0');

  const color = progress > 0.5 ? '#22c55e' : progress > 0.25 ? '#f59e0b' : '#ef4444';

  return (
    <View style={s.container}>
      <Svg width={SIZE} height={SIZE}>
        <Circle cx={SIZE / 2} cy={SIZE / 2} r={R} stroke="#1e293b" strokeWidth={STROKE} fill="none" />
        <Circle
          cx={SIZE / 2} cy={SIZE / 2} r={R}
          stroke={color} strokeWidth={STROKE} fill="none"
          strokeDasharray={`${CIRCUMFERENCE} ${CIRCUMFERENCE}`}
          strokeDashoffset={dashOffset}
          strokeLinecap="round"
          rotation="-90" origin={`${SIZE / 2}, ${SIZE / 2}`}
        />
      </Svg>
      <View style={s.label}>
        <Text style={[s.time, { color }]}>{minutes}:{seconds}</Text>
        <Text style={s.sub}>remaining</Text>
      </View>
    </View>
  );
}

const s = StyleSheet.create({
  container: { alignItems: 'center', justifyContent: 'center', marginVertical: 24 },
  label:     { position: 'absolute', alignItems: 'center' },
  time:      { fontSize: 36, fontWeight: 'bold' },
  sub:       { color: '#64748b', fontSize: 13 },
});

