import { useEffect, useState, useCallback } from 'react';
import { GoogleMap, useJsApiLoader, Circle, Marker } from '@react-google-maps/api';
import { getAllHotspots, getAllSignals, listIncidents } from '../utils/api';
import SignalMarker from '../components/SignalMarker';
import StatsBar from '../components/StatsBar';

const MAPS_KEY = import.meta.env.VITE_GOOGLE_MAPS_KEY || '';

const KARACHI_CENTER = { lat: 24.8607, lng: 67.0104 };
const RISK_COLORS = { HIGH: '#ef4444', MEDIUM: '#f59e0b', LOW: '#22c55e' };

export default function Heatmap() {
  const [hotspots, setHotspots]   = useState([]);
  const [signals, setSignals]     = useState([]);
  const [incidents, setIncidents] = useState([]);
  const [layers, setLayers]       = useState({ hotspots: true, signals: true, incidents: false });
  const [map, setMap]             = useState(null);

  const { isLoaded } = useJsApiLoader({ googleMapsApiKey: MAPS_KEY });

  useEffect(() => {
    getAllHotspots().then(r => setHotspots(r.data)).catch(console.warn);
    getAllSignals().then(r => setSignals(r.data)).catch(console.warn);
    listIncidents().then(r => setIncidents(r.data)).catch(console.warn);
  }, []);

  const onLoad = useCallback(m => setMap(m), []);

  const topDangerSignal = signals
    .filter(s => s.current_risk_level === 'HIGH')
    .sort((a, b) => b.current_risk_score - a.current_risk_score)[0];

  if (!isLoaded) return <div style={s.loading}>Loading map…</div>;

  return (
    <div style={s.container}>
      <StatsBar
        hotspotCount={hotspots.length}
        signalCount={signals.filter(s => s.current_risk_level === 'HIGH').length}
        incidentCount={incidents.length}
        topSignal={topDangerSignal?.name}
      />

      {/* Layer toggles */}
      <div style={s.controls}>
        {Object.keys(layers).map(k => (
          <button key={k} style={{ ...s.chip, opacity: layers[k] ? 1 : 0.4 }}
            onClick={() => setLayers(l => ({ ...l, [k]: !l[k] }))}>
            {k}
          </button>
        ))}
      </div>

      <GoogleMap
        mapContainerStyle={s.map}
        center={KARACHI_CENTER}
        zoom={12}
        onLoad={onLoad}
        options={{ styles: darkMapStyle }}
      >
        {/* Hotspot zones */}
        {layers.hotspots && hotspots.map((h, i) => (
          <Circle key={i}
            center={{ lat: h.center_lat, lng: h.center_lng }}
            radius={h.radius_meters}
            options={{
              fillColor: RISK_COLORS[h.risk_level],
              fillOpacity: 0.25,
              strokeColor: RISK_COLORS[h.risk_level],
              strokeWeight: 1,
            }}
          />
        ))}

        {/* Signal pins */}
        {layers.signals && signals.map((sig, i) => (
          <SignalMarker key={i} signal={sig} />
        ))}

        {/* Incident dots */}
        {layers.incidents && incidents.map((inc, i) => (
          <Marker key={i}
            position={{ lat: inc.lat, lng: inc.lng }}
            icon={{ path: 0, scale: 5, fillColor: '#ef4444', fillOpacity: 0.8, strokeWeight: 0 }}
          />
        ))}
      </GoogleMap>
    </div>
  );
}

const s = {
  container: { display: 'flex', flexDirection: 'column', height: '100vh', background: '#0f172a' },
  loading:   { color: '#f8fafc', display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' },
  map:       { flex: 1 },
  controls:  { display: 'flex', gap: 8, padding: '8px 16px', background: '#1e293b' },
  chip:      { background: '#334155', color: '#f8fafc', border: 'none', borderRadius: 20, padding: '6px 14px', cursor: 'pointer', textTransform: 'capitalize' },
};

const darkMapStyle = [
  { elementType: 'geometry', stylers: [{ color: '#1e293b' }] },
  { elementType: 'labels.text.fill', stylers: [{ color: '#94a3b8' }] },
  { featureType: 'road', elementType: 'geometry', stylers: [{ color: '#334155' }] },
  { featureType: 'water', elementType: 'geometry', stylers: [{ color: '#0f172a' }] },
];

