import { useEffect, useState } from 'react';
import { GoogleMap, useJsApiLoader, Marker, InfoWindow } from '@react-google-maps/api';
import { getAllSignals } from '../utils/api';
import { LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer } from 'recharts';

const MAPS_KEY = import.meta.env.VITE_GOOGLE_MAPS_KEY || '';
const KARACHI_CENTER = { lat: 24.8607, lng: 67.0104 };
const PIN_COLORS = { HIGH: '#ef4444', MEDIUM: '#f59e0b', LOW: '#22c55e' };

export default function SafeSignalsMap() {
  const [signals, setSignals]   = useState([]);
  const [selected, setSelected] = useState(null);
  const [filter, setFilter]     = useState('ALL');

  const { isLoaded } = useJsApiLoader({ googleMapsApiKey: MAPS_KEY });

  useEffect(() => {
    getAllSignals().then(r => setSignals(r.data)).catch(console.warn);
  }, []);

  const hour = new Date().getHours();
  const filtered = signals.filter(s => {
    if (filter === 'HIGH') return s.current_risk_level === 'HIGH';
    if (filter === 'NOW')  return s.peak_hours?.includes(hour);
    return true;
  });

  if (!isLoaded) return <div style={s.loading}>Loading…</div>;

  return (
    <div style={s.container}>
      <div style={s.sidebar}>
        <h2 style={s.title}>🚦 Signal Risk Map</h2>
        <p style={s.sub}>All Karachi signals, scored in real time</p>

        <div style={s.filterRow}>
          {['ALL','HIGH','NOW'].map(f => (
            <button key={f} style={{ ...s.chip, background: filter === f ? '#ef4444' : '#334155' }}
              onClick={() => setFilter(f)}>
              {f === 'NOW' ? '⚡ Right now' : f}
            </button>
          ))}
        </div>

        <div style={s.legend}>
          <span style={s.dot('#ef4444')} /> High risk
          <span style={s.dot('#f59e0b')} /> Medium
          <span style={s.dot('#22c55e')} /> Safe
        </div>

        <div style={s.signalList}>
          {filtered.filter(s => s.current_risk_level === 'HIGH').slice(0, 10).map((sig, i) => (
            <div key={i} style={s.signalItem} onClick={() => setSelected(sig)}>
              <span style={s.signalName}>{sig.name}</span>
              <span style={{ color: '#ef4444', fontSize: 12 }}>{sig.incident_count_week} incidents/wk</span>
            </div>
          ))}
        </div>
      </div>

      <GoogleMap
        mapContainerStyle={s.map}
        center={KARACHI_CENTER}
        zoom={12}
        options={{ styles: darkMapStyle }}
      >
        {filtered.map((sig, i) => (
          <Marker key={i}
            position={{ lat: sig.lat, lng: sig.lng }}
            onClick={() => setSelected(sig)}
            icon={{
              path: window.google.maps.SymbolPath.CIRCLE,
              scale: 8,
              fillColor: PIN_COLORS[sig.current_risk_level],
              fillOpacity: 0.9,
              strokeColor: '#fff',
              strokeWeight: 1.5,
            }}
          />
        ))}

        {selected && (
          <InfoWindow
            position={{ lat: selected.lat, lng: selected.lng }}
            onCloseClick={() => setSelected(null)}
          >
            <div style={s.infoWindow}>
              <strong>{selected.name}</strong>
