import { useState } from 'react';
import { reportIncident } from '../utils/api';

const INCIDENT_TYPES = [
  { id: 'phone_snatching', label: '🏍️ Phone Snatching (Biker)' },
  { id: 'ride_hailing',    label: '🚗 Ride-Hailing Incident' },
  { id: 'mugging',         label: '👊 Street Mugging (Armed)' },
  { id: 'signal_robbery',  label: '🚦 Signal Robbery' },
  { id: 'harassment',      label: '😰 Harassment' },
  { id: 'other',           label: '📋 Other' },
];

const KARACHI_SIGNALS = [
  'Teen Talwar Signal', 'Numaish Signal', 'Hassan Square', 'Baloch Colony Signal',
  'Gulshan Chowrangi', 'Tariq Road Signal', 'Shahra-e-Faisal Signal', 'Other',
];

export default function Report() {
  const [type, setType]   = useState('');
  const [sig, setSig]     = useState('');
  const [desc, setDesc]   = useState('');
  const [anon, setAnon]   = useState(true);
  const [status, setStatus] = useState('');

  const submit = async (e) => {
    e.preventDefault();
    setStatus('Submitting...');
    try {
      await reportIncident({
        type, lat: 24.8607, lng: 67.0104, // TODO: get from map pin
        signal_name: sig || null, description: desc, anonymous: anon,
      });
      setStatus('Thank you — your report has been recorded.');
      setType(''); setSig(''); setDesc('');
    } catch {
      setStatus('Error submitting. Try again.');
    }
  };

  return (
    <div style={s.container}>
      <h2 style={s.title}>Report an Incident</h2>
      <form onSubmit={submit} style={s.form}>
        <label style={s.label}>Incident Type</label>
        <div style={s.typeGrid}>
          {INCIDENT_TYPES.map(t => (
            <button type="button" key={t.id}
              style={{ ...s.typeBtn, background: type === t.id ? '#ef4444' : '#1e293b' }}
              onClick={() => setType(t.id)}>
              {t.label}
            </button>
          ))}
        </div>

        {(type === 'signal_robbery' || type === 'phone_snatching') && (
          <>
            <label style={s.label}>Signal Name</label>
            <select style={s.input} value={sig} onChange={e => setSig(e.target.value)}>
              <option value="">Select signal…</option>
              {KARACHI_SIGNALS.map(s => <option key={s} value={s}>{s}</option>)}
            </select>
          </>
        )}

        <label style={s.label}>Description (optional)</label>
        <textarea style={{ ...s.input, height: 100, resize: 'vertical' }}
          value={desc} onChange={e => setDesc(e.target.value)}
          placeholder="Brief description…" />

        <label style={s.checkRow}>
          <input type="checkbox" checked={anon} onChange={e => setAnon(e.target.checked)} />
          <span style={s.checkLabel}>Submit anonymously (recommended)</span>
        </label>

        <button type="submit" style={s.btn} disabled={!type}>Submit Report</button>
        {status && <p style={s.status}>{status}</p>}
      </form>
    </div>
  );
}

const s = {
  container: { maxWidth: 600, margin: '60px auto', padding: '0 24px', fontFamily: 'sans-serif' },
  title:     { color: '#f8fafc', fontSize: 28, marginBottom: 24 },
  form:      { display: 'flex', flexDirection: 'column', gap: 16 },
  label:     { color: '#94a3b8', fontSize: 13 },
  typeGrid:  { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8 },
  typeBtn:   { color: '#f8fafc', border: 'none', borderRadius: 10, padding: '12px 8px', cursor: 'pointer', fontSize: 14, textAlign: 'left' },
  input:     { background: '#1e293b', color: '#f8fafc', border: 'none', borderRadius: 10, padding: 12, fontSize: 14 },
  checkRow:  { display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer' },
  checkLabel:{ color: '#94a3b8', fontSize: 14 },
  btn:       { background: '#ef4444', color: '#fff', border: 'none', borderRadius: 12, padding: '14px', fontSize: 15, cursor: 'pointer', fontWeight: 600 },
  status:    { color: '#22c55e', fontSize: 14 },
};

