import { useEffect, useState } from 'react';
import { getAllHotspots, getAllSignals, listIncidents } from '../utils/api';
import IncidentCard from '../components/IncidentCard';
import StatsBar from '../components/StatsBar';

export default function Dashboard() {
  const [hotspots, setHotspots]   = useState([]);
  const [signals, setSignals]     = useState([]);
  const [incidents, setIncidents] = useState([]);

  useEffect(() => {
    getAllHotspots().then(r => setHotspots(r.data)).catch(console.warn);
    getAllSignals().then(r => setSignals(r.data)).catch(console.warn);
    listIncidents().then(r => setIncidents(r.data)).catch(console.warn);
  }, []);

  const topSignal = signals
    .filter(s => s.current_risk_level === 'HIGH')
    .sort((a, b) => b.current_risk_score - a.current_risk_score)[0];

  return (
    <div style={s.container}>
      <h1 style={s.title}>🛡️ Bachao Pakistan — Dashboard</h1>
      <StatsBar
        hotspotCount={hotspots.length}
        signalCount={signals.filter(s => s.current_risk_level === 'HIGH').length}
        incidentCount={incidents.length}
        topSignal={topSignal?.name}
      />

      <div style={s.section}>
        <h2 style={s.sectionTitle}>Recent Incidents</h2>
