  const date = new Date(incident.datetime || incident.created_at).toLocaleString('en-PK', {
    dateStyle: 'short', timeStyle: 'short',
  });

  return (
    <div style={s.card}>
      <div style={s.header}>
        <span style={s.icon}>{icon}</span>
        <span style={s.type}>{incident.type?.replace(/_/g, ' ')}</span>
      </div>
      {incident.signal_name && <p style={s.signal}>📍 {incident.signal_name}</p>}
      {incident.description && <p style={s.desc}>{incident.description}</p>}
      <p style={s.date}>{date}</p>
    </div>
  );
}

const s = {
  card:   { background: '#1e293b', borderRadius: 12, padding: 16, borderLeft: '3px solid #ef4444' },
  header: { display: 'flex', alignItems: 'center', gap: 8, marginBottom: 8 },
  icon:   { fontSize: 20 },
  type:   { color: '#f8fafc', fontSize: 14, fontWeight: 600, textTransform: 'capitalize' },
  signal: { color: '#94a3b8', fontSize: 13, margin: '4px 0' },
  desc:   { color: '#cbd5e1', fontSize: 13, margin: '4px 0' },
  date:   { color: '#475569', fontSize: 12, marginTop: 8 },
};

