import { useState } from 'react';
import { Marker, InfoWindow } from '@react-google-maps/api';

const PIN_COLORS = { HIGH: '#ef4444', MEDIUM: '#f59e0b', LOW: '#22c55e' };

export default function SignalMarker({ signal }) {
  const [open, setOpen] = useState(false);
  const color = PIN_COLORS[signal.current_risk_level] || '#94a3b8';

  return (
    <>
      <Marker
        position={{ lat: signal.lat, lng: signal.lng }}
        onClick={() => setOpen(true)}
        icon={{
          path: window.google?.maps?.SymbolPath?.CIRCLE || 0,
          scale: 7,
          fillColor: color,
          fillOpacity: 0.9,
          strokeColor: '#fff',
          strokeWeight: 1.5,
        }}
      />
      {open && (
        <InfoWindow
          position={{ lat: signal.lat, lng: signal.lng }}
          onCloseClick={() => setOpen(false)}
        >
          <div style={s.popup}>
            <strong style={{ color }}>{signal.name}</strong>
            <p>Risk: <b style={{ color }}>{signal.current_risk_level}</b></p>
            <p>This week: {signal.incident_count_week} incidents</p>
            <p>This month: {signal.incident_count_month} incidents</p>
            <p>Peak: {signal.peak_hours?.join('h, ')}h</p>
            {signal.incident_types?.[0] && <p>Most common: {signal.incident_types[0]}</p>}
          </div>
        </InfoWindow>
      )}
    </>
  );
}

const s = {
  popup: { background: '#1e293b', color: '#f8fafc', padding: '4px 8px', minWidth: 180, fontSize: 13 },
};

