import { GoogleMap, useJsApiLoader } from '@react-google-maps/api';

const MAPS_KEY = import.meta.env.VITE_GOOGLE_MAPS_KEY || '';

export default function MapView({ center, zoom = 12, children, style = {} }) {
  const { isLoaded } = useJsApiLoader({ googleMapsApiKey: MAPS_KEY });

  if (!isLoaded) return <div style={{ ...style, display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#94a3b8' }}>Loading map…</div>;

  return (
    <GoogleMap
      mapContainerStyle={{ width: '100%', height: '100%', ...style }}
      center={center}
      zoom={zoom}
      options={{
        styles: [
          { elementType: 'geometry', stylers: [{ color: '#1e293b' }] },
          { elementType: 'labels.text.fill', stylers: [{ color: '#94a3b8' }] },
          { featureType: 'road', elementType: 'geometry', stylers: [{ color: '#334155' }] },
          { featureType: 'water', elementType: 'geometry', stylers: [{ color: '#0f172a' }] },
        ],
      }}
    >
      {children}
    </GoogleMap>
  );
}

